window.AUTH=window.AUTH||{};window.AUTH["16-1011"]={"d":"16-1011","id":"2017/16-1011","n":"WesternGeco LLC v. ION Geophysical Corp.","briefs":[{"k":"petitioner","label":"Brief of petitioner WesternGeco LLC","date":"2018-02-23","url":"https://www.supremecourt.gov/DocketPDF/16/16-1011/36393/20180223141640636_16-1011-ts.pdf","side":"pet","n":95},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-03-02","url":"https://www.supremecourt.gov/DocketPDF/16/16-1011/37393/20180302141329389_16-1011tsacUnitedStates.pdf","side":"us","n":38},{"k":"respondent","label":"Brief of respondent ION Geophysical Corporation","date":"2018-03-26","url":"https://www.supremecourt.gov/DocketPDF/16/16-1011/40106/20180326192128171_ION%20brief%20for%20respondent.PDF","side":"res","n":69},{"k":"reply","label":"Reply of petitioner WesternGeco LLC","date":"2018-04-09","url":"https://www.supremecourt.gov/DocketPDF/16/16-1011/42748/20180409125016912_16-1011rb.pdf","side":"pet","n":24}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"sum":"The Court held that backpay should be awarded based on a court’s discretion. The decision in this case should be considered in light of the goals of the Equal Employment Opportunity Act. Because the prospect of a backpay award could ensure the use of equal employment practices, it serves the purposes of the Act and should be awarded in this case.","sumSrc":"Oyez","by":{"0":"24","1":"5"}},{"t":"case","label":"Am. Banana Co. v. United States","cite":"213 U.S. 347","y":1909,"id":"scdb/1908-135","sc":1,"sum":"While a country may treat some relations between its own citizens as governed by its own law in regions subject to no sovereign, like the high seas, or to no law recognized as adequate, the general rule is that the character of an act as lawful or unlawful must be determined wholly by the law of the country where it is done.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"29, 46"}},{"t":"case","label":"Am. Safety Table Co. v. Schreiber","cite":"415 F.2d 373","y":1969,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/415/373/","by":{"0":"10, 24"}},{"t":"case","label":"Aro Mfg. Co. v. Convertible Top Replacement Co.","cite":"377 U.S. 476","y":1964,"id":"1963/75","sc":1,"sum":"Respondent was the assignee of certain territorial rights in a combination patent for a top-structure for convertible automobiles. The patent covered only the combination of several unpatented components and made no claim to invention based on the fabric used in the top-structure. Top-structures using the patented combination were included in 1952-1954 cars made by General Motors Corp., pursuant to a patent license, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 52","1":"3, 11, 17"}},{"t":"case","label":"Bavendam v. Pearson Educ., Inc.","cite":"2013 WL 5530008","y":2013,"court":"D.N.J. Oct. 3","by":{"0":"51"}},{"t":"case","label":"Bende & Sons, Inc. v. Crown Recreation, Inc.","cite":"548 F. Supp. 1018","y":1982,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./548/1018/","by":{"0":"45"}},{"t":"case","label":"Carbice Corp. of Am. v. Am. Patents Dev. Corp.","cite":"283 U.S. 27","y":1931,"id":"scdb/1930-027","sc":1,"by":{"0":"52"}},{"t":"case","label":"Carleton v. Lombard, Ayres & Co.","cite":"43 N.E. 422","y":1896,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./43/422/","by":{"0":"46"}},{"t":"case","label":"Commil USA, LLC v. Cisco Sys., Inc.","cite":"135 S. Ct. 1920","y":2015,"id":"2014/13-896","sc":1,"sum":"The Court decided that a good-faith belief that a patent is invalid is not a defense to a claim of induced infringement.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Coupe v. Royer","cite":"155 U.S. 565","y":1895,"id":"scdb/1894-062","sc":1,"sum":"In letters patent No. 77,920, granted to Herman Royer and Louis Royer, May 12, 1868, for “ an improved machine for treating hides,” the first claim, viz., for “ a vertical shaft,” and the second claim, viz., for a “ grooved weight,” are restricted to a shaft and crib in a vertical position, and to a weight operating by the force of gravity aided by pressure; and they cannot be extended so as to include shafts and …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Datascope Corp. v. SMEC, Inc.","cite":"879 F.2d 820","y":1989,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/879/820/","by":{"0":"44","2":"42"}},{"t":"case","label":"Deauville Corp. v. Federated Dep’t Stores, Inc.","cite":"756 F.2d 1183","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/756/1183/","by":{"0":"45"}},{"t":"case","label":"Deepsouth Packing Co. v. Laitram Corp.","cite":"406 U.S. 518","y":1972,"id":"1971/71-315","sc":1,"sum":"Petitioner is not foreclosed by 35 U. S. C. § 271 (a), which proscribes the unauthorized making of any patented invention within the United States, from making, the parts of shrimp deveining machines (for which respondent was adjudged to have valid combination patents) to sell to foreign buyers for assembly by the buyers for use abroad. The word \"makes\" as used in § 271 (a) does not extend to the manufacture of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 7, 8, 23","1":"22","2":"4, 27, 29","3":"1"}},{"t":"case","label":"Delafield v. J.K. Armsby Co.","cite":"116 N.Y.S. 71","y":1909,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S./116/71/","by":{"0":"45"}},{"t":"case","label":"Dowagiac Mfg. Co. v. Minn. Moline Plow Co.","cite":"235 U.S. 641","y":1915,"id":"scdb/1914-255","sc":1,"ar":3,"sum":"Where a patent is infringed by selling machines embodying improvements covered by the patent and the value of the machines as marketable articles is attributable in part to the patented improvements and in part to unpatented parts or features, the profits arising from the infringing sales belong to the owner of the patent in so far as they are attributable to the patented improvements, and in so far as they are due …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42","1":"6, 8, 16, 17, 18","2":"passim","3":"18"}},{"t":"case","label":"eBay Inc. v. MercExchange, L.L.C.","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"sum":"Held that the appeals court's general rule was an unwarranted departure from the traditional four-part test applied to determine whether an injunction is necessary.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Edwards Mfg. Co. v. Bradford Co.","cite":"294 F. 176","y":1923,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F./294/176/","by":{"0":"45","2":"43"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"ar":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29","1":"24","2":"15"}},{"t":"case","label":"F. Hoffmann-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"0":"32","1":"24","2":"22, 47"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","2":"38"}},{"t":"case","label":"Fishel v. Lueckel","cite":"53 F. 499","y":1892,"court":"C.C.S.D.N.Y.","url":"https://www.courtlistener.com/c/F./53/499/","by":{"0":"44","1":"21"}},{"t":"case","label":"Fox Film Corp. v. Doyal","cite":"286 U.S. 123","y":1932,"id":"scdb/1931-096","sc":1,"sum":"1. A privilege tax on a business of licensing copyrighted motion pictures, measured by the gross receipts of royalties, is in effect a direct charge upon the royalties. EducationalFilms Corp. v. Ward, 282 U. S. 379, distinguished. P. 126. Argument for Appellant.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"General Motors Corp. v. Devex Corp.","cite":"461 U.S. 648","y":1983,"id":"1982/81-1661","sc":1,"sum":"The award of prejudgment interest was proper in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"45","3":"3, 20"}},{"t":"case","label":"Geophysical Serv. Inc. v. ConocoPhillips Co.","cite":"2016 WL 2839286","y":2016,"court":"S.D. Tex. May 13","by":{"0":"51"}},{"t":"case","label":"Glob.-Tech Appliances v. SEB S.A.","cite":"563 U.S. 754","y":2011,"id":"2010/10-6","sc":1,"sum":"The Court ruled that induced infringement under the patent clause requires knowledge that the induced acts constitute patent infringement.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Goulds Mfg. Co. v. Cowing","cite":"105 U.S. 253","y":1881,"id":"scdb/1881-137","sc":1,"ar":7,"by":{"0":"20, 42","1":"6, 8, 16, 17","2":"passim","3":"18"}},{"t":"case","label":"Great White Bear, LLC v. Mervyns, LLC","cite":"2008 WL 2220662","y":2008,"court":"S.D.N.Y. May 27","by":{"0":"45"}},{"t":"case","label":"Halo Elecs., Inc. v. Pulse Elecs., Inc.","cite":"136 S. Ct. 1923","y":2016,"id":"2015/14-1513","sc":1,"sum":"The Court determined that the rigid two-part test is not necessary for determining whether a patentee is eligible for enhanced damages under 35 U.S.C §284.","sumSrc":"Oyez","by":{"0":"17","1":"6","2":"11"}},{"t":"case","label":"Hardwood Lumber Co. v. Adam & Steinbrugge","cite":"68 S.E. 725","y":1910,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./68/725/","by":{"0":"45"}},{"t":"case","label":"ICONICS, Inc. v. Massaro","cite":"192 F. Supp. 3d 254","y":2016,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/192/254/","by":{"0":"51"}},{"t":"case","label":"Ketchum Harvester Co. v. Johnson Harvester Co.","cite":"8 F. 586","y":1881,"court":"C.C.N.D.N.Y.","url":"https://www.courtlistener.com/c/F./8/586/","by":{"0":"43, 44, 52","1":"18, 19, 21","2":"42","3":"7, 8, 18"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"ar":1,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"0":"28, 33","1":"24","2":"passim"}},{"t":"case","label":"Kirby Lumber Co. v. C.R. Cummings & Co.","cite":"122 SW. 273","y":1909,"court":"Tex. Civ. App.","url":"https://www.courtlistener.com/c/SW./122/273/","by":{"0":"45"}},{"t":"case","label":"L.A. News Serv. v. Reuters Television Int'l, Ltd.","cite":"340 F.3d 926","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/340/926/","by":{"0":"50","2":"45, 46"}},{"t":"case","label":"Laitram Corp. v. Deepsouth Packing Co.","cite":"301 F. Supp. 1037","y":1969,"court":"E.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp./301/1037/","by":{"0":"7"}},{"t":"case","label":"Lauritzen v. Larsen","cite":"345 U.S. 571","y":1953,"id":"scdb/1952-093","sc":1,"sum":"The court had jurisdiction to determine whether the asserted cause of action was well founded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"134 S. Ct. 1377","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Liberty Toy Co. v. Fred Silber Co.","cite":"149 F.3d 1183","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/149/1183/","by":{"0":"50"}},{"t":"case","label":"Life Techs. Corp. v. Promega Corp.","cite":"137 S. Ct. 734","y":2017,"id":"2016/14-1538","sc":1,"sum":"The Court held that supplying a single component of a multi-component invention from the United States for sale abroad does not expose the manufacturer to liability for infringement based on worldwide sales.","sumSrc":"Oyez","by":{"0":"8, 31, 35","1":"2, 22","2":"5"}},{"t":"case","label":"Limelight Networks, Inc. v. Akamai Techs., Inc.","cite":"134 S. Ct. 2111","y":2014,"id":"2013/12-786","sc":1,"ar":1,"sum":"The Court held that a party is not liable for patent infringement under 35 U.S.C. § 271(b) unless the party has also violated Section 217(a)o or any other statutory provision.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"McComb v. Brodie","cite":"15 F. Cas. 1290","y":1872,"court":"C.C.D. La.","url":"https://www.courtlistener.com/c/F.%20Cas./15/1290/","by":{"0":"10, 24"}},{"t":"case","label":"Microsoft Corp. v. AT&T Corp.","cite":"550 U.S. 437","y":2007,"id":"2006/05-1056","sc":1,"ar":3,"sum":"The Court ruled 7-1 that Microsoft was not liable for infringement of AT&T's patent. The opinion by Justice Ruth Bader Ginsburg held that \"software code is an idea without physical embodiment\"; it cannot be a component of a patented invention.","sumSrc":"Oyez","by":{"0":"passim","1":"23","2":"passim"}},{"t":"case","label":"Millmaker v. Bruso","cite":"2008 WL 219551","y":2008,"court":"S.D. Tex. Jan. 25","by":{"0":"45"}},{"t":"case","label":"Morrison v. Nat’l Austl. Bank, Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"ar":2,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"0":"28, 29","1":"27, 30, 31","2":"passim"}},{"t":"case","label":"Multiflex, Inc. v. Samuel Moore & Co.","cite":"709 F.2d 980","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/709/980/","by":{"0":"45","2":"42"}},{"t":"case","label":"Palmer v. Braun","cite":"376 F.3d 1254","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/1254/","by":{"0":"50, 51"}},{"t":"case","label":"Palmer/Kane LLC v. Houghton Mifflin Harcourt Publ’g Co.","cite":"2014 WL 183774","y":2014,"court":"D. Mass. Jan. 16","by":{"0":"51"}},{"t":"case","label":"Panduit v. Stahlin Bros. Fibre Works, Inc.","cite":"575 F.2d 1152","y":1978,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/575/1152/","by":{"0":"10, 24, 53","1":"3"}},{"t":"case","label":"Piaggio & C. v. Cushman Motor Works","cite":"416 F.2d 683","y":1969,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/416/683/","by":{"0":"45","2":"43"}},{"t":"case","label":"Power Integrations, Inc. v. Fairchild Semiconductor Int’l, Inc.","cite":"589 F. Supp. 2d 505","y":2008,"court":"D. Del.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/589/505/","by":{"0":"15"}},{"t":"case","label":"Power Integrations, Inc. v. Fairchild Semiconductor Int’l, Inc.","cite":"711 F.3d 1348","y":2013,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/711/1348/","by":{"0":"15, 43, 48","1":"5","2":"9"}},{"t":"case","label":"R.R. Dynamics, Inc. v. A. Stucki Co.","cite":"727 F.2d 1506","y":1984,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/727/1506/","by":{"0":"44","2":"42"}},{"t":"case","label":"Rite-Hite Corp. v. Kelley Co., Inc.","cite":"56 F.3d 1538","y":1995,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/56/1538/","ar":1,"by":{"0":"10, 24, 53","1":"11","2":"51"}},{"t":"case","label":"RJR Nabisco, Inc. v. European Cmty.","cite":"136 S. Ct. 2090","y":2016,"id":"2015/15-138","sc":1,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"0":"28, 33, 47","1":"passim","2":"passim","3":"5, 9, 13"}},{"t":"case","label":"Robinson v. Hyer","cite":"17 So. 745","y":1895,"court":"Fla.","url":"https://www.courtlistener.com/c/So./17/745/","by":{"0":"45"}},{"t":"case","label":"Schillinger v. United States","cite":"155 U.S. 163","y":1894,"id":"scdb/1894-019","sc":1,"sum":"The United States cannot be sued in their courts without their consent.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"52","1":"10","3":"6"}},{"t":"case","label":"Schneider (Eur.) AG v. Scimed Life Sys.","cite":"60 F.3d 839","y":1995,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/60/839/","by":{"0":"44","2":"42"}},{"t":"case","label":"Sekhar v. United States","cite":"133 S. Ct. 2720","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Sheldon v. Metro-Goldwyn Pictures Corp.","cite":"106 F.2d 45","y":1939,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/106/45/","by":{"0":"44, 49, 50","1":"8, 21","2":"43, 44, 45","3":"21"}},{"t":"case","label":"Sheldon v. Metro-Goldwyn Pictures Corp.","cite":"309 U.S. 390","y":1940,"id":"scdb/1939-111","sc":1,"sum":"1. That clause of § 25 (b) of the Copyright Act which authorizes recovery from an infringer, \"in lieu of actual damages and profits,\" of \"such 'damages as to the court shall appear to be just,\" is inapplicable where the only matter in question is the apportionment of profits established.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Siemens Med. Sols. USA, Inc. v. Saint-Gobain Ceramics & Plastics, Inc.","cite":"637 F.3d 1269","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/637/1269/","by":{"0":"10, 24"}},{"t":"case","label":"Smith v. United States","cite":"507 U.S. 197","y":1993,"id":"1992/91-1538","sc":1,"sum":"The FTCA does not apply to tortious acts or omissions occurring in Antarctica. The ordinary meaning of \"foreign country\" includes Antarctica, even though it has no recognized government. If this were not so, § 1346(b)-which waives sovereign immunity for certain torts committed \"under circumstances where the United States, if a private person, would be liable... in accordance with the law of the place where the act …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","1":"23","2":"17, 53"}},{"t":"case","label":"Snead v. United States","cite":"595 F. Supp. 658","y":1984,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./595/658/","by":{"0":"45"}},{"t":"case","label":"Sony Corp. of Am. v. Universal City Studios, Inc.","cite":"464 U.S. 417","y":1984,"id":"1982/81-1687","sc":1,"sum":"The Court held that \"[t]he sale of the VTR's to the general public does not constitute contributory infringement of [Universal's] copyrights.\" The Court concluded that there was a significant likelihood that a substantial number of copyright holders who license their works for free public broadcasts would not object to having their broadcasts time-shifted by private viewers and that Universal failed to show that time-shifting would cause non-minimal harm to the potential market for, or the value of, their copyrighted works.","sumSrc":"Oyez","by":{"0":"51, 52","1":"20"}},{"t":"case","label":"Sun-Maid Raisin Growers v. Victor Packing Co.","cite":"194 Cal. Rptr. 612","y":1983,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr./194/612/","by":{"0":"45"}},{"t":"case","label":"Tire Eng’g & Distrib., LLC v. Shandong Linglong Rubber Co.","cite":"682 F.3d 292","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/682/292/","sum":"Describing the doctrine as “fundamental”.","sumSrc":"brief:0","by":{"0":"44, 50, 51","1":"20","2":"45"}},{"t":"case","label":"Update Art, Inc. v. Modiin Publ’g, Ltd.","cite":"843 F.2d 67","y":1988,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/843/67/","by":{"0":"50","1":"20","2":"45"}},{"t":"case","label":"Wallingford v. Kaiser","cite":"84 N.E. 295","y":1908,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./84/295/","by":{"0":"46"}},{"t":"case","label":"Yale Lock Mfg. Co. v. Sargent","cite":"117 U.S. 536","y":1886,"id":"scdb/1885-206","sc":1,"sum":"Claim 1 of reissued letters patent No. 4696, granted to James Sargent, January 2, 1872, for an “improvement in looks,” on an application, fded September 25,'1871, the original patent, No. 57,574,' having been granted to him August 28, 1866, namely, “ 1. In a combination lock for safe or vault doors, a-bolt, I,which turns on a pivot or bearing,, when said bolt, 1, is used in a lock having no ordinary sliding …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"10, 18, 24, 25","1":"3, 11","2":"6","3":"4, 20"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","by":{"0":"40"}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","by":{"0":"40"}},{"t":"usc","label":"15 U.S.C. § 77v","url":"https://www.law.cornell.edu/uscode/text/15/77v","by":{"0":"40"}},{"t":"usc","label":"15 U.S.C. § 77x","url":"https://www.law.cornell.edu/uscode/text/15/77x","by":{"0":"40"}},{"t":"usc","label":"15 U.S.C. § 78aa","url":"https://www.law.cornell.edu/uscode/text/15/78aa","by":{"0":"40"}},{"t":"usc","label":"15 U.S.C. § 78ff","url":"https://www.law.cornell.edu/uscode/text/15/78ff","by":{"0":"40"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","by":{"0":"40"}},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","subs":["(c)"],"stext":{"head":"§1964. Civil remedies","paras":[[0,"(a) The district courts of the United States shall have jurisdiction to prevent and restrain violations of section 1962 of this chapter by issuing appropriate orders, including, but not limited to: ordering any person to divest himself of any interest, direct or indirect, in any enterprise; imposing reasonable restrictions on the future activities or investments of any person, including, but not limited to, prohibiting any person from engaging in the same type of endeavor as the enterprise engaged in, the activities of which affect interstate or foreign commerce; or ordering dissolution or reorganization of any enterprise, making due provision for the rights of innocent persons."],[0,"(b) The Attorney General may institute proceedings under this section. Pending final determination thereof, the court may at any time enter such restraining orders or prohibitions, or take such other actions, including the acceptance of satisfactory performance bonds, as it shall deem proper."],[0,"(c) Any person injured in his business or property by reason of a violation of section 1962 of this chapter may sue therefor in any appropriate United States district court and shall recover threefold the damages he sustains and the cost of the suit, including a reasonable attorney's fee, except that no person may rely upon any conduct that would have been actionable as fraud in the purchase or sale of securities to establish a violation of section 1962. The exception contained in the preceding sentence does not apply to an action against any person that is criminally convicted in connection with the fraud, in which case the statute of limitations shall start to run on the date on which the conviction becomes final."],[0,"(d) A final judgment or decree rendered in favor of the United States in any criminal proceeding brought by the United States under this chapter shall estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding brought by the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1964?type=usc&year=mostrecent&link-type=html"},"head":"§1964. Civil remedies","tname":"Crimes and Criminal Procedure","by":{"0":"33","2":"17","3":"5, 8"}},{"t":"usc","label":"29 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/29/211","by":{"0":"40"}},{"t":"usc","label":"29 U.S.C. § 215","url":"https://www.law.cornell.edu/uscode/text/29/215","by":{"0":"40"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","by":{"0":"40"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(c)","(c)(1)"],"stext":{"head":"§626. Recordkeeping, investigation, and enforcement","paras":[[0,"(a) Attendance of witnesses; investigations, inspections, records, and homework regulations"],[0,"The Equal Employment Opportunity Commission shall have the power to make investigations and require the keeping of records necessary or appropriate for the administration of this chapter in accordance with the powers and procedures provided in sections 209 and 211 of this title."],[0,"(b) Enforcement; prohibition of age discrimination under fair labor standards; unpaid minimum wages and unpaid overtime compensation; liquidated damages; judicial relief; conciliation, conference, and persuasion"],[0,"The provisions of this chapter shall be enforced in accordance with the powers, remedies, and procedures provided in sections 211(b), 216 (except for subsection (a) thereof), and 217 of this title, and subsection (c) of this section. Any act prohibited under section 623 of this title shall be deemed to be a prohibited act under section 215 of this title. Amounts owing to a person as a result of a violation of this chapter shall be deemed to be unpaid minimum wages or unpaid overtime compensation for purposes of sections 216 and 217 of this title: Provided, That liquidated damages shall be payable only in cases of willful violations of this chapter. In any action brought to enforce this chapter the court shall have jurisdiction to grant such legal or equitable relief as may be appropriate to effectuate the purposes of this chapter, including without limitation judgments compelling employment, reinstatement or promotion, or enforcing the liability for amounts deemed to be unpaid minimum wages or unpaid overtime compensation under this section. Before instituting any action under this section, the Equal Employment Opportunity Commission shall attempt to eliminate the discriminatory practice or practices alleged, and to effect voluntary compliance with the requirements of this chapter through informal methods of conciliation, conference, and persuasion."],[0,"(c) Civil actions; persons aggrieved; jurisdiction; judicial relief; termination of individual action upon commencement of action by Commission; jury trial"],[0,"(1) Any person aggrieved may bring a civil action in any court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter: Provided, That the right of any person to bring such action shall terminate upon the commencement of an action by the Equal Employment Opportunity Commission to enforce the right of such employee under this chapter."],[0,"(2) In an action brought under paragraph (1), a person shall be entitled to a trial by jury of any issue of fact in any such action for recovery of amounts owing as a result of a violation of this chapter, regardless of whether equitable relief is sought by any party in such action."],[0,"(d) Filing of charge with Commission; timeliness; conciliation, conference, and persuasion; unlawful practice"],[0,"(1) No civil action may be commenced by an individual under this section until 60 days after a charge alleging unlawful discrimination has been filed with the Equal Employment Opportunity Commission. Such a charge shall be filed—"],[1,"(A) within 180 days after the alleged unlawful practice occurred; or"],[1,"(B) in a case to which section 633(b) of this title applies, within 300 days after the alleged unlawful practice occurred, or within 30 days after receipt by the individual of notice of termination of proceedings under State law, whichever is earlier."],[0,"(2) Upon receiving such a charge, the Commission shall promptly notify all persons named in such charge as prospective defendants in the action and shall promptly seek to eliminate any alleged unlawful practice by informal methods of conciliation, conference, and persuasion."],[0,"(3) For purposes of this section, an unlawful practice occurs, with respect to discrimination in compensation in violation of this chapter, when a discriminatory compensation decision or other practice is adopted, when a person becomes subject to a discriminatory compensation decision or other practice, or when a person is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(e) Reliance on administrative rulings; notice of dismissal or termination; civil action after receipt of notice"],[0,"Section 259 of this title shall apply to actions under this chapter. If a charge filed with the Commission under this chapter is dismissed or the proceedings of the Commission are otherwise terminated by the Commission, the Commission shall notify the person aggrieved. A civil action may be brought under this section by a person defined in section 630(a) of this title against the respondent named in the charge within 90 days after the date of the receipt of such notice."],[0,"(f) Waiver"],[0,"(1) An individual may not waive any right or claim under this chapter unless the waiver is knowing and voluntary. Except as provided in paragraph (2), a waiver may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) the waiver is part of an agreement between the individual and the employer that is written in a manner calculated to be understood by such individual, or by the average individual eligible to participate;"],[1,"(B) the waiver specifically refers to rights or claims arising under this chapter;"],[1,"(C) the individual does not waive rights or claims that may arise after the date the waiver is executed;"],[1,"(D) the individual waives rights or claims only in exchange for consideration in addition to anything of value to which the individual already is entitled;"],[1,"(E) the individual is advised in writing to consult with an attorney prior to executing the agreement;"],[1,"(F)(i) the individual is given a period of at least 21 days within which to consider the agreement; or"],[1,"(ii) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the individual is given a period of at least 45 days within which to consider the agreement;"],[1,"(G) the agreement provides that for a period of at least 7 days following the execution of such agreement, the individual may revoke the agreement, and the agreement shall not become effective or enforceable until the revocation period has expired;"],[1,"(H) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the employer (at the commencement of the period specified in subparagraph (F)) informs the individual in writing in a manner calculated to be understood by the average individual eligible to participate, as to—"],[2,"(i) any class, unit, or group of individuals covered by such program, any eligibility factors for such program, and any time limits applicable to such program; and"],[2,"(ii) the job titles and ages of all individuals eligible or selected for the program, and the ages of all individuals in the same job classification or organizational unit who are not eligible or selected for the program."],[0,"(2) A waiver in settlement of a charge filed with the Equal Employment Opportunity Commission, or an action filed in court by the individual or the individual's representative, alleging age discrimination of a kind prohibited under section 623 or 633a of this title may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) subparagraphs (A) through (E) of paragraph (1) have been met; and"],[1,"(B) the individual is given a reasonable period of time within which to consider the settlement agreement."],[0,"(3) In any dispute that may arise over whether any of the requirements, conditions, and circumstances set forth in subparagraph (A), (B), (C), (D), (E), (F), (G), or (H) of paragraph (1), or subparagraph (A) or (B) of paragraph (2), have been met, the party asserting the validity of a waiver shall have the burden of proving in a court of competent jurisdiction that a waiver was knowing and voluntary pursuant to paragraph (1) or (2)."],[0,"(4) No waiver agreement may affect the Commission's rights and responsibilities to enforce this chapter. No waiver may be used to justify interfering with the protected right of an employee to file a charge or participate in an investigation or proceeding conducted by the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/626?type=usc&year=mostrecent&link-type=html"},"head":"§626. Recordkeeping, investigation, and enforcement","tname":"Labor","by":{"0":"40","2":"32, 33"}},{"t":"usc","label":"35 U.S.C. § 67","url":"https://www.law.cornell.edu/uscode/text/35/67","subs":["(1946)"],"by":{"0":"10"}},{"t":"usc","label":"35 U.S.C. § 70","url":"https://www.law.cornell.edu/uscode/text/35/70","subs":["(1946)"],"by":{"0":"10"}},{"t":"usc","label":"35 U.S.C. § 154","url":"https://www.law.cornell.edu/uscode/text/35/154","subs":["(a)(1)"],"stext":{"head":"§154. Contents and term of patent; provisional rights","paras":[[0,"(a) In General.—"],[1,"(1) Contents.—Every patent shall contain a short title of the invention and a grant to the patentee, his heirs or assigns, of the right to exclude others from making, using, offering for sale, or selling the invention throughout the United States or importing the invention into the United States, and, if the invention is a process, of the right to exclude others from using, offering for sale or selling throughout the United States, or importing into the United States, products made by that process, referring to the specification for the particulars thereof."],[1,"(2) Term.—Subject to the payment of fees under this title, such grant shall be for a term beginning on the date on which the patent issues and ending 20 years from the date on which the application for the patent was filed in the United States or, if the application contains a specific reference to an earlier filed application or applications under section 120, 121, 365(c), or 386(c), from the date on which the earliest such application was filed."],[1,"(3) Priority.—Priority under section 119, 365(a), 365(b), 386(a), or 386(b) shall not be taken into account in determining the term of a patent."],[1,"(4) Specification and drawing.—A copy of the specification and drawing shall be annexed to the patent and be a part of such patent."],[0,"(b) Adjustment of Patent Term.—"],[1,"(1) Patent term guarantees.—"],[2,"(A) Guarantee of prompt patent and trademark office responses.—Subject to the limitations under paragraph (2), if the issue of an original patent is delayed due to the failure of the Patent and Trademark Office to—"],[3,"(i) provide at least one of the notifications under section 132 or a notice of allowance under section 151 not later than 14 months after—"],[4,"(I) the date on which an application was filed under section 111(a); or"],[4,"(II) the date of commencement of the national stage under section 371 in an international application;"],[3,"(ii) respond to a reply under section 132, or to an appeal taken under section 134, within 4 months after the date on which the reply was filed or the appeal was taken;"],[3,"(iii) act on an application within 4 months after the date of a decision by the Patent Trial and Appeal Board under section 134 or 135 or a decision by a Federal court under section 141, 145, or 146 in a case in which allowable claims remain in the application; or"],[3,"(iv) issue a patent within 4 months after the date on which the issue fee was paid under section 151 and all outstanding requirements were satisfied,"],[2,"the term of the patent shall be extended 1 day for each day after the end of the period specified in clause (i), (ii), (iii), or (iv), as the case may be, until the action described in such clause is taken."],[2,"(B) Guarantee of no more than 3-year application pendency.—Subject to the limitations under paragraph (2), if the issue of an original patent is delayed due to the failure of the United States Patent and Trademark Office to issue a patent within 3 years after the actual filing date of the application under section 111(a) in the United States or, in the case of an international application, the date of commencement of the national stage under section 371 in the international application, not including—"],[3,"(i) any time consumed by continued examination of the application requested by the applicant under section 132(b);"],[3,"(ii) any time consumed by a proceeding under section 135(a), any time consumed by the imposition of an order under section 181, or any time consumed by appellate review by the Patent Trial and Appeal Board or by a Federal court; or"],[3,"(iii) any delay in the processing of the application by the United States Patent and Trademark Office requested by the applicant except as permitted by paragraph (3)(C),"],[2,"the term of the patent shall be extended 1 day for each day after the end of that 3-year period until the patent is issued."],[2,"(C) Guarantee of adjustments for delays due to derivation proceedings, secrecy orders, and appeals.—Subject to the limitations under paragraph (2), if the issue of an original patent is delayed due to—"],[3,"(i) a proceeding under section 135(a);"],[3,"(ii) the imposition of an order under section 181; or"],[3,"(iii) appellate review by the Patent Trial and Appeal Board or by a Federal court in a case in which the patent was issued under a decision in the review reversing an adverse determination of patentability,"],[2,"the term of the patent shall be extended 1 day for each day of the pendency of the proceeding, order, or review, as the case may be."],[1,"(2) Limitations.—"],[2,"(A) In general.—To the extent that periods of delay attributable to grounds specified in paragraph (1) overlap, the period of any adjustment granted under this subsection shall not exceed the actual number of days the issuance of the patent was delayed."],[2,"(B) Disclaimed term.—No patent the term of which has been disclaimed beyond a specified date may be adjusted under this section beyond the expiration date specified in the disclaimer."],[2,"(C) Reduction of period of adjustment.—"],[3,"(i) The period of adjustment of the term of a patent under paragraph (1) shall be reduced by a period equal to the period of time during which the applicant failed to engage in reasonable efforts to conclude prosecution of the application."],[3,"(ii) With respect to adjustments to patent term made under the authority of paragraph (1)(B), an applicant shall be deemed to have failed to engage in reasonable efforts to conclude processing or examination of an application for the cumulative total of any periods of time in excess of 3 months that are taken to respond to a notice from the Office making any rejection, objection, argument, or other request, measuring such 3-month period from the date the notice was given or mailed to the applicant."],[3,"(iii) The Director shall prescribe regulations establishing the circumstances that constitute a failure of an applicant to engage in reasonable efforts to conclude processing or examination of an application."],[1,"(3) Procedures for patent term adjustment determination.—"],[2,"(A) The Director shall prescribe regulations establishing procedures for the application for and determination of patent term adjustments under this subsection."],[2,"(B) Under the procedures established under subparagraph (A), the Director shall—"],[3,"(i) make a determination of the period of any patent term adjustment under this subsection, and shall transmit a notice of that determination no later than the date of issuance of the patent; and"],[3,"(ii) provide the applicant one opportunity to request reconsideration of any patent term adjustment determination made by the Director."],[2,"(C) The Director shall reinstate all or part of the cumulative period of time of an adjustment under paragraph (2)(C) if the applicant, prior to the issuance of the patent, makes a showing that, in spite of all due care, the applicant was unable to respond within the 3-month period, but in no case shall more than three additional months for each such response beyond the original 3-month period be reinstated."],[2,"(D) The Director shall proceed to grant the patent after completion of the Director's determination of a patent term adjustment under the procedures established under this subsection, notwithstanding any appeal taken by the applicant of such determination."],[1,"(4) Appeal of patent term adjustment determination.—"],[2,"(A) An applicant dissatisfied with the Director's decision on the applicant's request for reconsideration under paragraph (3)(B)(ii) shall have exclusive remedy by a civil action against the Director filed in the United States District Court for the Eastern District of Virginia within 180 days after the date of the Director's decision on the applicant's request for reconsideration. Chapter 7 of title 5 shall apply to such action. Any final judgment resulting in a change to the period of adjustment of the patent term shall be served on the Director, and the Director shall thereafter alter the term of the patent to reflect such change."],[2,"(B) The determination of a patent term adjustment under this subsection shall not be subject to appeal or challenge by a third party prior to the grant of the patent."],[0,"(c) Continuation.—"],[1,"(1) Determination.—The term of a patent that is in force on or that results from an application filed before the date that is 6 months after the date of the enactment of the Uruguay Round Agreements Act shall be the greater of the 20-year term as provided in subsection (a), or 17 years from grant, subject to any terminal disclaimers."],[1,"(2) Remedies.—The remedies of sections 283, 284, and 285 shall not apply to acts which—"],[2,"(A) were commenced or for which substantial investment was made before the date that is 6 months after the date of the enactment of the Uruguay Round Agreements Act; and"],[2,"(B) became infringing by reason of paragraph (1)."],[1,"(3) Remuneration.—The acts referred to in paragraph (2) may be continued only upon the payment of an equitable remuneration to the patentee that is determined in an action brought under chapter 28 and chapter 29 (other than those provisions excluded by paragraph (2))."],[0,"(d) Provisional Rights.—"],[1,"(1) In general.—In addition to other rights provided by this section, a patent shall include the right to obtain a reasonable royalty from any person who, during the period beginning on the date of publication of the application for such patent under section 122(b), or in the case of an international application filed under the treaty defined in section 351(a) designating the United States under Article 21(2)(a) of such treaty or an international design application filed under the treaty defined in section 381(a)(1) designating the United States under Article 5 of such treaty, the date of publication of the application, and ending on the date the patent is issued—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/154?type=usc&year=mostrecent&link-type=html"},"head":"§154. Contents and term of patent; provisional rights","tname":"Patents","by":{"0":"6","2":"4","3":"6"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","subs":["(a)","(b)","(c)","(f)","(f)(1)","(f)(2)"],"stext":{"head":"§271. Infringement of patent","paras":[[0,"(a) Except as otherwise provided in this title, whoever without authority makes, uses, offers to sell, or sells any patented invention, within the United States or imports into the United States any patented invention during the term of the patent therefor, infringes the patent."],[0,"(b) Whoever actively induces infringement of a patent shall be liable as an infringer."],[0,"(c) Whoever offers to sell or sells within the United States or imports into the United States a component of a patented machine, manufacture, combination or composition, or a material or apparatus for use in practicing a patented process, constituting a material part of the invention, knowing the same to be especially made or especially adapted for use in an infringement of such patent, and not a staple article or commodity of commerce suitable for substantial noninfringing use, shall be liable as a contributory infringer."],[0,"(d) No patent owner otherwise entitled to relief for infringement or contributory infringement of a patent shall be denied relief or deemed guilty of misuse or illegal extension of the patent right by reason of his having done one or more of the following: (1) derived revenue from acts which if performed by another without his consent would constitute contributory infringement of the patent; (2) licensed or authorized another to perform acts which if performed without his consent would constitute contributory infringement of the patent; (3) sought to enforce his patent rights against infringement or contributory infringement; (4) refused to license or use any rights to the patent; or (5) conditioned the license of any rights to the patent or the sale of the patented product on the acquisition of a license to rights in another patent or purchase of a separate product, unless, in view of the circumstances, the patent owner has market power in the relevant market for the patent or patented product on which the license or sale is conditioned."],[0,"(e)(1) It shall not be an act of infringement to make, use, offer to sell, or sell within the United States or import into the United States a patented invention (other than a new animal drug or veterinary biological product (as those terms are used in the Federal Food, Drug, and Cosmetic Act and the Act of March 4, 1913) which is primarily manufactured using recombinant DNA, recombinant RNA, hybridoma technology, or other processes involving site specific genetic manipulation techniques) solely for uses reasonably related to the development and submission of information under a Federal law which regulates the manufacture, use, or sale of drugs or veterinary biological products."],[0,"(2) It shall be an act of infringement to submit—"],[1,"(A) an application under section 505(j) of the Federal Food, Drug, and Cosmetic Act or described in section 505(b)(2) of such Act for a drug claimed in a patent or the use of which is claimed in a patent,"],[1,"(B) an application under section 512 of such Act or under the Act of March 4, 1913 (21 U.S.C. 151–158) for a drug or veterinary biological product which is not primarily manufactured using recombinant DNA, recombinant RNA, hybridoma technology, or other processes involving site specific genetic manipulation techniques and which is claimed in a patent or the use of which is claimed in a patent, or"],[1,"(C)(i) with respect to a patent that is identified in the list of patents described in section 351(l)(3) of the Public Health Service Act (including as provided under section 351(l)(7) of such Act), an application seeking approval of a biological product, or"],[1,"(ii) if the applicant for the application fails to provide the application and information required under section 351(l)(2)(A) of such Act, an application seeking approval of a biological product for a patent that could be identified pursuant to section 351(l)(3)(A)(i) of such Act,"],[0,"if the purpose of such submission is to obtain approval under such Act to engage in the commercial manufacture, use, or sale of a drug, veterinary biological product, or biological product claimed in a patent or the use of which is claimed in a patent before the expiration of such patent."],[0,"(3) In any action for patent infringement brought under this section, no injunctive or other relief may be granted which would prohibit the making, using, offering to sell, or selling within the United States or importing into the United States of a patented invention under paragraph (1)."],[0,"(4) For an act of infringement described in paragraph (2)—"],[1,"(A) the court shall order the effective date of any approval of the drug or veterinary biological product involved in the infringement to be a date which is not earlier than the date of the expiration of the patent which has been infringed,"],[1,"(B) injunctive relief may be granted against an infringer to prevent the commercial manufacture, use, offer to sell, or sale within the United States or importation into the United States of an approved drug, veterinary biological product, or biological product,"],[1,"(C) damages or other monetary relief may be awarded against an infringer only if there has been commercial manufacture, use, offer to sell, or sale within the United States or importation into the United States of an approved drug, veterinary biological product, or biological product, and"],[1,"(D) the court shall order a permanent injunction prohibiting any infringement of the patent by the biological product involved in the infringement until a date which is not earlier than the date of the expiration of the patent that has been infringed under paragraph (2)(C), provided the patent is the subject of a final court decision, as defined in section 351(k)(6) of the Public Health Service Act, in an action for infringement of the patent under section 351(l)(6) of such Act, and the biological product has not yet been approved because of section 351(k)(7) of such Act."],[0,"The remedies prescribed by subparagraphs (A), (B), (C), and (D) are the only remedies which may be granted by a court for an act of infringement described in paragraph (2), except that a court may award attorney fees under section 285."],[0,"(5) Where a person has filed an application described in paragraph (2) that includes a certification under subsection (b)(2)(A)(iv) or (j)(2)(A)(vii)(IV) of section 505 of the Federal Food, Drug, and Cosmetic Act (21 U.S.C. 355), and neither the owner of the patent that is the subject of the certification nor the holder of the approved application under subsection (b) of such section for the drug that is claimed by the patent or a use of which is claimed by the patent brought an action for infringement of such patent before the expiration of 45 days after the date on which the notice given under subsection (b)(3) or (j)(2)(B) of such section was received, the courts of the United States shall, to the extent consistent with the Constitution, have subject matter jurisdiction in any action brought by such person under section 2201 of title 28 for a declaratory judgment that such patent is invalid or not infringed."],[0,"(6)(A) Subparagraph (B) applies, in lieu of paragraph (4), in the case of a patent—"],[1,"(i) that is identified, as applicable, in the list of patents described in section 351(l)(4) of the Public Health Service Act or the lists of patents described in section 351(l)(5)(B) of such Act with respect to a biological product; and"],[1,"(ii) for which an action for infringement of the patent with respect to the biological product—"],[2,"(I) was brought after the expiration of the 30-day period described in subparagraph (A) or (B), as applicable, of section 351(l)(6) of such Act; or"],[2,"(II) was brought before the expiration of the 30-day period described in subclause (I), but which was dismissed without prejudice or was not prosecuted to judgment in good faith."],[0,"(B) In an action for infringement of a patent described in subparagraph (A), the sole and exclusive remedy that may be granted by a court, upon a finding that the making, using, offering to sell, selling, or importation into the United States of the biological product that is the subject of the action infringed the patent, shall be a reasonable royalty."],[0,"(C) The owner of a patent that should have been included in the list described in section 351(l)(3)(A) of the Public Health Service Act, including as provided under section 351(l)(7) of such Act for a biological product, but was not timely included in such list, may not bring an action under this section for infringement of the patent with respect to the biological product."],[0,"(f)(1) Whoever without authority supplies or causes to be supplied in or from the United States all or a substantial portion of the components of a patented invention, where such components are uncombined in whole or in part, in such manner as to actively induce the combination of such components outside of the United States in a manner that would infringe the patent if such combination occurred within the United States, shall be liable as an infringer."],[0,"(2) Whoever without authority supplies or causes to be supplied in or from the United States any component of a patented invention that is especially made or especially adapted for use in the invention and not a staple article or commodity of commerce suitable for substantial noninfringing use, where such component is uncombined in whole or in part, knowing that such component is so made or adapted and intending that such component will be combined outside of the United States in a manner that would infringe the patent if such combination occurred within the United States, shall be liable as an infringer."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/271?type=usc&year=mostrecent&link-type=html"},"head":"§271. Infringement of patent","tname":"Patents","by":{"0":"passim","2":"4, 5, 46, 4, 9, 29, 4, 4, passim, 5, passim","3":"passim"}},{"t":"usc","label":"35 U.S.C. § 281","url":"https://www.law.cornell.edu/uscode/text/35/281","stext":{"head":"§281. Remedy for infringement of patent","paras":[[0,"A patentee shall have remedy by civil action for infringement of his patent."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/281?type=usc&year=mostrecent&link-type=html"},"head":"§281. Remedy for infringement of patent","tname":"Patents","by":{"0":"6","2":"5","3":"9"}},{"t":"usc","label":"35 U.S.C. § 284","url":"https://www.law.cornell.edu/uscode/text/35/284","stext":{"head":"§284. Damages","paras":[[0,"Upon finding for the claimant the court shall award the claimant damages adequate to compensate for the infringement, but in no event less than a reasonable royalty for the use made of the invention by the infringer, together with interest and costs as fixed by the court."],[0,"When the damages are not found by a jury, the court shall assess them. In either event the court may increase the damages up to three times the amount found or assessed. Increased damages under this paragraph shall not apply to provisional rights under section 154(d)."],[0,"The court may receive expert testimony as an aid to the determination of damages or of what royalty would be reasonable under the circumstances."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/284?type=usc&year=mostrecent&link-type=html"},"ar":4,"head":"§284. Damages","tname":"Patents","by":{"0":"9","2":"passim","3":"passim"}},{"t":"usc","label":"42 U.S.C. § 12111","url":"https://www.law.cornell.edu/uscode/text/42/12111","by":{"0":"40"}},{"t":"usc","label":"42 U.S.C. § 12112","url":"https://www.law.cornell.edu/uscode/text/42/12112","by":{"0":"40"}},{"t":"usc","label":"42 U.S.C. § 12117","url":"https://www.law.cornell.edu/uscode/text/42/12117","by":{"0":"40"}},{"t":"usc","label":"42 U.S.C. § 1981a","url":"https://www.law.cornell.edu/uscode/text/42/1981a","by":{"0":"40"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"0":"40"}},{"t":"usc","label":"46 U.S.C. § 70503","url":"https://www.law.cornell.edu/uscode/text/46/70503","by":{"0":"40"}},{"t":"usc","label":"46 U.S.C. § 70506","url":"https://www.law.cornell.edu/uscode/text/46/70506","by":{"0":"40"}},{"t":"law","label":"Pub. L. No. 82-593","url":"https://www.govinfo.gov/link/statute/66/792","by":{"0":"9","2":"passim"}},{"t":"case","label":"Adriance, Platt & Co. v. McCormick Harvesting Mach. Co.","cite":"55 F. 288","y":1893,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F./55/288/","by":{"1":"19"}},{"t":"case","label":"(III) Cases—Continued: Bullock Elec. & Mfg. Co. v. Westinghouse Elec. & Mfg. Co.","cite":"129 F. 105","y":1904,"url":"https://www.courtlistener.com/c/F./129/105/","by":{"1":"19"}},{"t":"case","label":"Carnegie Mellon Univ. v. Marvell Tech. Grp., Ltd.","cite":"807 F.3d 1283","y":2015,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/807/1283/","ar":2,"sum":"Explaining that royalties in an action under Section 271(a) are domestic when they are awarded for articles manufactured, sold, or used in the United States.","sumSrc":"brief:2","by":{"1":"23","2":"passim"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Dorsey Revolving Harvester Rake Co. v. Bradley Mfg. Co.","cite":"7 F. Cas. 946","y":1874,"court":"C.C.N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Cas./7/946/","by":{"1":"19, 20"}},{"t":"case","label":"Impression Prods., Inc. v. Lexmark Int’ l, Inc.","cite":"137 S. Ct. 1523","y":2017,"id":"2016/15-1189","sc":1,"sum":"The Court determined that a patentee’s decision to sell an item exhausts all of its patent rights in that item, even if the e patentee purports to impose post-sale restrictions, and regardless of whether the sale occurs domestically or internationally.","sumSrc":"Oyez","by":{"1":"26, 27"}},{"t":"case","label":"K. W. Ignition Co. v. Temco Elec. Motor Co.","cite":"283 F. 873","y":1922,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F./283/873/","by":{"1":"8, 19","2":"42"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Los Angeles News Serv. v. Reuters Television Int’ l, Ltd.","cite":"149 F.3d 987","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/149/987/","ar":1,"by":{"1":"20"}},{"t":"case","label":"Lucent Techs., Inc. v. Gateway, Inc.","cite":"580 F.3d 1301","y":2009,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/580/1301/","by":{"1":"3"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Wisconsin v. Mitchell","cite":"508 U.S. 476","y":1993,"id":"1992/92-515","sc":1,"sum":"The Court found that the Wisconsin statute paralleled antidiscrimination laws which had been found to comply with the First Amendment. It also determined that the consequences for the victim and the community tended to be more severe, when the victim of a crime was chosen on account of his or her race.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Alice Corp. v. CLS Bank International","cite":"134 S. Ct. 2347","y":2014,"id":"2013/13-298","sc":1,"ar":1,"sum":"The Court found that patent laws should not place restraints on abstract ideas that form the \"building blocks of human ingenuity.\"","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"sum":"The FSIA provides the sole basis for obtaining jurisdiction over a foreign state in United States courts, and the District Court correctly dismissed the action because the FSIA did not authorize jurisdiction over petitioner under the facts of this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17, 20"}},{"t":"case","label":"Astoria Federal Savings & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Birdsall v. Coolidge","cite":"93 U.S. 64","y":1876,"id":"scdb/1876-012","sc":1,"sum":"Submitted on' printed arguments by Mr. O. J. Hillyer for the appellants, and by Mr. A. H. Hvans for the appellee.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"44"}},{"t":"case","label":"Blatchford v. Native Village of Noatak & Circle Village","cite":"501 U.S. 775","y":1991,"id":"1990/89-1782","sc":1,"sum":"Respondents, Alaska Native villages, brought suit against petitioner, a state official, seeking an order requiring payment to them of money allegedly owed under a state revenue-sharing statute. The District Court dismissed the suit as violating the Eleventh Amendment. The Court of Appeals reversed, first on the ground that 28 U. S. C. § 1362 constituted a congressional abrogation of Eleventh Amendment immunity, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Chicago & Southern Air Lines, Inc. v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"2":"51"}},{"t":"case","label":"European Community v. RJR Nabisco, Inc.","cite":"764 F.3d 149","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/764/149/","by":{"2":"50"}},{"t":"case","label":"Feres v. United States","cite":"340 U.S. 135","y":1950,"id":"scdb/1950-013","sc":1,"by":{"2":"38"}},{"t":"case","label":"Gardiner v. Howe","cite":"9 F. Cas. 1157","y":1865,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./9/1157/","by":{"2":"53"}},{"t":"case","label":"Martha’s Vineyard Scuba Headquarters, Inc. v. Unidentified Vessel","cite":"833 F.2d 1059","y":1987,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/833/1059/","by":{"2":"53"}},{"t":"case","label":"Milwaukee & St. Paul Railway Co. v. Kellogg","cite":"94 U.S. 469","y":1876,"id":"scdb/1876-197","sc":1,"by":{"2":"51"}},{"t":"case","label":"On-Line Technologies, Inc. v. Perkin-Elmer Corp.","cite":"428 F. Supp. 2d 76","y":2006,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/428/76/","by":{"2":"51"}},{"t":"case","label":"Parks v. Booth","cite":"102 U.S. 96","y":1880,"id":"scdb/1879-192","sc":1,"sum":"T. Reissued letters-pátent No. 1826, granted Nov. 29, 1864, to Jonathan L. Booth for a new and useful improvement in grain-separators, áre.valid.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"Sale v. Haitian Centers Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"sum":"And, it found that both section 243(h) and Article 33 are silent regarding extraterritorial application. In fact, the language of both suggests that only individuals who have already arrived on United States soil are protected, and their use throughout history confirms this interpretation. Thus, the judgment of the Court of Appeals is reversed.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Sedima, S.P.R.L. v. Imrex Co.","cite":"473 U.S. 479","y":1985,"id":"1984/84-648","sc":1,"sum":"The Racketeer Influenced and Corrupt Organizations Act (RICO), 18 U. S. C. §§ 1961-1968, which is directed at \"racketeering activity\"defined in § 1961(1) to encompass, inter alia,acts \"indictable\" under specific federal criminal provisions, including mail and wire fraud-provides in § 1964(c) for a private civil action to recover treble damages by any person injured in his business or property \"by reason of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40"}},{"t":"case","label":"W.S. Tyler Co. v. Ludlow-Saylor Wire Co.","cite":"236 U.S. 723","y":1915,"id":"scdb/1914-190","sc":1,"sum":"Paying an agent, who is also employed by another corporation, to solicit orders to be executed at its home officé and sharing expenses with another corporation of an office in the District in which a suit for infringement of patent is brought, held in this case not to amount to having a regular and established place of business which would subject a foreign corporation to the jurisdiction of the Federal court under …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"41, 42"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"2":"53"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"2":"32"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","by":{"2":"18"}},{"t":"usc","label":"28 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/28/2671","by":{"2":"38"}},{"t":"law","label":"Pub. L. No. 98-622","url":"https://www.govinfo.gov/link/statute/98/3383","by":{"2":"5"}},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","by":{"2":"passim"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","stext":{"head":"§1962. Prohibited activities","paras":[[0,"(a) It shall be unlawful for any person who has received any income derived, directly or indirectly, from a pattern of racketeering activity or through collection of an unlawful debt in which such person has participated as a principal within the meaning of section 2, title 18, United States Code, to use or invest, directly or indirectly, any part of such income, or the proceeds of such income, in acquisition of any interest in, or the establishment or operation of, any enterprise which is engaged in, or the activities of which affect, interstate or foreign commerce. A purchase of securities on the open market for purposes of investment, and without the intention of controlling or participating in the control of the issuer, or of assisting another to do so, shall not be unlawful under this subsection if the securities of the issuer held by the purchaser, the members of his immediate family, and his or their accomplices in any pattern or racketeering activity or the collection of an unlawful debt after such purchase do not amount in the aggregate to one percent of the outstanding securities of any one class, and do not confer, either in law or in fact, the power to elect one or more directors of the issuer."],[0,"(b) It shall be unlawful for any person through a pattern of racketeering activity or through collection of an unlawful debt to acquire or maintain, directly or indirectly, any interest in or control of any enterprise which is engaged in, or the activities of which affect, interstate or foreign commerce."],[0,"(c) It shall be unlawful for any person employed by or associated with any enterprise engaged in, or the activities of which affect, interstate or foreign commerce, to conduct or participate, directly or indirectly, in the conduct of such enterprise's affairs through a pattern of racketeering activity or collection of unlawful debt."],[0,"(d) It shall be unlawful for any person to conspire to violate any of the provisions of subsection (a), (b), or (c) of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1962?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1962. Prohibited activities","tname":"Crimes and Criminal Procedure","by":{"2":"17"}},{"t":"usc","label":"17 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/17/504","stext":{"head":"§504. Remedies for infringement: Damages and profits","paras":[[0,"(a) In General.—Except as otherwise provided by this title, an infringer of copyright is liable for either—"],[1,"(1) the copyright owner's actual damages and any additional profits of the infringer, as provided by subsection (b); or"],[1,"(2) statutory damages, as provided by subsection (c)."],[0,"(b) Actual Damages and Profits.—The copyright owner is entitled to recover the actual damages suffered by him or her as a result of the infringement, and any profits of the infringer that are attributable to the infringement and are not taken into account in computing the actual damages. In establishing the infringer's profits, the copyright owner is required to present proof only of the infringer's gross revenue, and the infringer is required to prove his or her deductible expenses and the elements of profit attributable to factors other than the copyrighted work."],[0,"(c) Statutory Damages.—"],[1,"(1) Except as provided by clause (2) of this subsection, the copyright owner may elect, at any time before final judgment is rendered, to recover, instead of actual damages and profits, an award of statutory damages for all infringements involved in the action, with respect to any one work, for which any one infringer is liable individually, or for which any two or more infringers are liable jointly and severally, in a sum of not less than $750 or more than $30,000 as the court considers just. For the purposes of this subsection, all the parts of a compilation or derivative work constitute one work."],[1,"(2) In a case where the copyright owner sustains the burden of proving, and the court finds, that infringement was committed willfully, the court in its discretion may increase the award of statutory damages to a sum of not more than $150,000. In a case where the infringer sustains the burden of proving, and the court finds, that such infringer was not aware and had no reason to believe that his or her acts constituted an infringement of copyright, the court in its discretion may reduce the award of statutory damages to a sum of not less than $200. The court shall remit statutory damages in any case where an infringer believed and had reasonable grounds for believing that his or her use of the copyrighted work was a fair use under section 107, if the infringer was: (i) an employee or agent of a nonprofit educational institution, library, or archives acting within the scope of his or her employment who, or such institution, library, or archives itself, which infringed by reproducing the work in copies or phonorecords; or (ii) a public broadcasting entity which or a person who, as a regular part of the nonprofit activities of a public broadcasting entity (as defined in section 118(f)) infringed by performing a published nondramatic literary work or by reproducing a transmission program embodying a performance of such a work."],[1,"(3)(A) In a case of infringement, it shall be a rebuttable presumption that the infringement was committed willfully for purposes of determining relief if the violator, or a person acting in concert with the violator, knowingly provided or knowingly caused to be provided materially false contact information to a domain name registrar, domain name registry, or other domain name registration authority in registering, maintaining, or renewing a domain name used in connection with the infringement."],[1,"(B) Nothing in this paragraph limits what may be considered willful infringement under this subsection."],[1,"(C) For purposes of this paragraph, the term \"domain name\" has the meaning given that term in section 45 of the Act entitled \"An Act to provide for the registration and protection of trademarks used in commerce, to carry out the provisions of certain international conventions, and for other purposes\" approved July 5, 1946 (commonly referred to as the \"Trademark Act of 1946\"; 15 U.S.C. 1127)."],[0,"(d) Additional Damages in Certain Cases.—In any case in which the court finds that a defendant proprietor of an establishment who claims as a defense that its activities were exempt under section 110(5) did not have reasonable grounds to believe that its use of a copyrighted work was exempt under such section, the plaintiff shall be entitled to, in addition to any award of damages under this section, an additional award of two times the amount of the license fee that the proprietor of the establishment concerned should have paid the plaintiff for such use during the preceding period of up to 3 years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/504?type=usc&year=mostrecent&link-type=html"},"head":"§504. Remedies for infringement: Damages and profits","tname":"Copyrights","by":{"2":"45","3":"21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"2":"2"}},{"t":"case","label":"Brulotte v. Thys Co.","cite":"379 U.S. 29","y":1964,"id":"1964/20","sc":1,"sum":"The royalty provisions of a patent-licensing agreement which provides for royalties for the use of machines incorporating certain patents are not enforceable for the period beyond the expiration of the last patent incorporated in the machine. Automatic Radio Co. v. Hazeltine, 339 U. S. 827, distinguished. Pp. 30-34. 62 Wash. 2d 284, 382 P. 2d 271, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"City of N. Vernon v. Voegler","cite":"2 N.E. 821","y":1885,"court":"Ind.","url":"https://www.courtlistener.com/c/N.E./2/821/","by":{"3":"7"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Goodyear v. Discala","cite":"849 A.2d 791","y":2004,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/849/791/","by":{"3":"7"}},{"t":"case","label":"Kimble v. Marvel Entm’t LLC","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Newton v. Merrill Lynch, Pierce, Fenner & Smith, Inc.","cite":"259 F.3d 154","y":2001,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/259/154/","by":{"3":"6"}},{"t":"case","label":"Util. Air Regulatory Grp. v. EPA","cite":"134 S. Ct. 2427","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2427/","sc":1,"by":{"3":"12"}},{"t":"case","label":"West v. St. Louis Pub. Serv. Co.","cite":"236 S.W.2d 308","y":1951,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/236/308/","by":{"3":"7"}}]};